import {HOSTED_URL,APP_VERSION} from './hosted-config.js';
import {createHostedConnection} from './hosted.js';
import {seal,open} from './vault.js';
import {validateRecords,mergeRecords} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=$('main'),storageKey='traptrack.v1';let pass='',records=[],draft={},step=0,unlocked=false,bridge=null,pending=new Map(),nonce='',cloudToken='',cloudReady=false;
let settings={};try{settings=JSON.parse(localStorage.getItem('traptrack.settings')||'{}')||{}}catch{};
let hostedInfo=null;
const hosted=createHostedConnection(window,()=>{cloudReady=true;if(location.hash==='#settings'||location.hash==='#setup')render();});
const phases=['Before','At the start','At the peak','After'];
const moods=[['calm','face-smile','Calm'],['sad','face-sad-tear','Sad'],['angry','face-angry','Angry'],['afraid','face-flushed','Afraid'],['joyful','face-laugh-beam','Joyful'],['unsure','face-meh','Unsure']];
const mixed={Overwhelmed:['Afraid','Sad','Angry'],Disappointed:['Sad','Angry'],Vulnerable:['Afraid','Sad'],Hopeful:['Joyful','Afraid'],Conflicted:['Angry','Sad','Joyful']};
function notify(s){$('#status').textContent=s;setTimeout(()=>$('#status').textContent='',6500)}
function apply(){document.body.className=(settings.theme==='purple'?'theme-purple ':'')+(settings.compact?'compact':'')};apply();
function button(label,action,cls=''){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function field(k,label,placeholder=''){return `<label for="${k}">${label}</label><textarea id="${k}" data-field="${k}" placeholder="${esc(placeholder)}" maxlength="4000">${esc(draft[k])}</textarea>`}
function home(){main.innerHTML=`<section class="hero"><div><span class="eyebrow">YOUR PATTERNS ARE NOT YOUR DESTINY</span><h1>Find the pause.<br>Choose your<br>next step.</h1><p>A gentler way to understand difficult moments, untangle your feelings, and practice a response that works better for you.</p><div class="actions"><a class="button primary" href="#journal">Make space to reflect <i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></a><a class="button" href="#learn">How it works</a></div><p class="hint">Your pace. Your words. No perfect answers required.</p></div><div class="art" aria-label="From an automatic pattern to an intentional next step"><div class="orb"></div><div class="pathcard"><small>NOTICE THE TRAP</small><strong>“I felt hurt. I shut down.”</strong><p>Understand what the pattern was doing for you.</p></div><div class="pathcard"><small>GET BACK ON TRAC</small><strong>“I can pause, then ask.”</strong><p>Try one small step toward what matters.</p></div></div></section><div class="sectionhead"><h2>A moment becomes a map.</h2><span class="hint">LEARN → REFLECT → REHEARSE</span></div><section class="grid"><article class="card"><span class="number">1</span><h3>Understand your loop</h3><p>Separate the event, your response, and the pattern that followed.</p></article><article class="card"><span class="number">2</span><h3>Check the temperature</h3><p>Notice feelings and intensity across the moment, with room for mixed emotions.</p></article><article class="card"><span class="number">3</span><h3>Prepare a different path</h3><p>Build a realistic plan you can return to before a similar situation.</p></article></section>`}
function learn(){main.innerHTML=`<div class="narrow"><span class="eyebrow">A SMALL GUIDE TO A DIFFERENT NEXT STEP</span><h1>Out of the TRAP.<br>Back on TRAC.</h1><p>Trap Track is this app’s name for a TRAP → TRAC reflection practice. The framework comes from behavioral activation, often used within CBT. It can sit alongside DBT skills; it is not presented here as an official DBT acronym.</p><div class="grid"><article class="card"><span class="number">T</span><h3>Trigger</h3><p>What happened? Describe observable facts, separate from what you assumed they meant.</p></article><article class="card"><span class="number">R</span><h3>Response</h3><p>What emotions, thoughts, body sensations, and urges appeared?</p></article><article class="card"><span class="number">AP</span><h3>Avoidance pattern</h3><p>What did you do to get away from discomfort? What relief did it give, and what did it cost later?</p></article></div><div class="notice"><b>TRAC keeps the Trigger and Response, then adds Alternative Coping.</b><p>You do not have to eliminate a feeling before choosing a workable action.</p></div><h2>A familiar example</h2><div class="flow"><b>Trigger</b>A friend hasn’t replied to my message.<br><b>Response</b>I feel afraid and hurt. I think, “I don’t matter.” My chest tightens.<br><b>Avoidance pattern</b>I mute the conversation and cancel plans. It helps briefly; later I feel more isolated.<br><b>Alternative coping</b>I pause, consider other explanations, then send one clear check-in when I’m ready.</div><h2>Use a record as rehearsal</h2><ol><li>Pick a recurring situation, not your hardest experience first.</li><li>Look for an early cue: a thought, tight jaw, faster heartbeat, or urge to leave.</li><li>Choose the outcome you want and one small action within your control.</li><li>Write: “If I notice ___, then I will ___.” Practice the words once.</li><li>After trying it, record what happened and adjust. A difficult outcome is information, not a failure.</li></ol><details><summary>DBT-informed options for your plan</summary><p>Pause and observe before acting; separate facts from interpretations; choose a clear request or boundary. Use any DBT skill you already know with guidance from your clinician. Opposite action is context-dependent, not a rule to ignore danger or override every feeling.</p></details><details><summary>What this tool can and cannot do</summary><p>This is an educational journal, not diagnosis, therapy, or an emergency service. It cannot guarantee fewer symptoms or a particular outcome. Stepping away may be protective; safety, boundaries, and rest are not automatically avoidance. You can skip any prompt or stop when you need to.</p></details><details><summary>Sources and terminology</summary><p><a href="https://www.miccsi.org/wp-content/uploads/2021/07/04-Behavioral-Activation_MCCIST.pdf" target="_blank" rel="noopener">MiCCSI: Behavioral Activation, TRAP & TRAC</a></p><p><a href="https://www.personal.kent.edu/~dfresco/CBT_Readings/CPSP_Jacobson_et_al_BA.pdf" target="_blank" rel="noopener">Jacobson and colleagues: behavioral activation treatment</a></p><p>Emotion combinations in this app are optional vocabulary suggestions, not universal formulas or clinical assessments.</p></details><div class="actions"><a class="button primary" href="#journal">Try a reflection</a></div></div>`}
function gate(){main.innerHTML=`<section class="narrow card"><span class="eyebrow">YOUR PRIVATE SPACE</span><h2>${localStorage.getItem(storageKey)?'Unlock your journal':'Create your journal'}</h2><p>Your entries are encrypted on this device before they are saved or sent to your own Google Sheet. Use a unique passphrase of at least 12 characters. It stays in memory until you lock or close this page.</p><label for="pass">Journal passphrase</label><input id="pass" type="password" autocomplete="current-password" minlength="12"><p class="hint">Keep it somewhere safe. There is no passphrase recovery. Anyone using an unlocked page can read your journal. Lock it on shared devices.</p>${button('Unlock journal','unlock','primary')} <a class="button" href="#learn">Learn first</a><p class="hint">No existing journal on this device? Use the same passphrase as your encrypted backup or Google Sheet.</p></section>`}
function moodBlock(i){const m=draft.temps?.[i]||{moods:[],intensity:null};return `<div class="card"><h3>${phases[i]} ${i===0?'the event':i===3?'the event':''}</h3><p class="hint">Choose any that fit. You can leave this unanswered.</p><div class="chips">${moods.map(([id,icon,label])=>`<button class="mood" data-mood="${id}" data-phase="${i}" aria-pressed="${m.moods.includes(id)}"><i class="fa-solid fa-${icon}" aria-hidden="true"></i>${label}</button>`).join('')}</div><label for="intensity${i}">Intensity: <output id="out${i}">${m.intensity??'not recorded'}</output> / 10</label><input id="intensity${i}" type="range" min="0" max="10" value="${m.intensity??0}" data-intensity="${i}" aria-label="${phases[i]} emotion intensity"><span class="hint">0 = no intensity · 10 = strongest for you</span><div class="actions"><button data-zero="${i}">Record 0</button><button data-clear-intensity="${i}">Clear rating</button></div><label for="own${i}">Your own feeling words</label><input id="own${i}" data-own="${i}" value="${esc(m.own)}" maxlength="200" placeholder="Numb, relieved, tense, something else…"></div>`}
function journal(){if(!unlocked)return gate();const names=['Set the scene','Feel the moment','Notice the pattern','Choose your next step','Review & save'];main.innerHTML=`<div class="narrow"><div class="sectionhead"><span class="eyebrow">A REFLECTION, NOT A REPORT CARD</span>${button('Pause & lock','lock')}</div><h2>${names[step]}</h2><p class="hint">Step ${step+1} of 5 · Skip any prompt that does not help. Draft stays in memory until saved.</p><div class="steps" aria-hidden="true">${names.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div id="stepcontent"></div><div class="actions">${step?button('Back','back'):''}${step<4?button('Continue','next','primary'):button('Save reflection','save','primary')}</div></div>`;const panel=$('#stepcontent');if(step===0)panel.innerHTML=`${field('title','Give this moment a name','A difficult conversation, waiting for a reply…')}<label for="date">When did it happen?</label><input id="date" type="datetime-local" data-field="date" value="${esc(draft.date)}">${field('trigger','T · What happened?','What could a camera have seen or heard?')}${field('context','What was already affecting you?','Sleep, hunger, pain, stress, a busy day…')}<label for="tags">Pattern tags (comma separated)</label><input id="tags" data-field="tags" value="${esc(draft.tags)}" placeholder="work, relationships, uncertainty">`;if(step===1)panel.innerHTML=`<p>Track how the feeling changed. A mixed feeling can contain several emotions, and it may mean something different for you.</p><label for="mixed">Explore a mixed feeling</label><select id="mixed"><option value="">Choose a word to explore</option>${Object.keys(mixed).map(x=>`<option>${x}</option>`).join('')}</select><div id="mixhint" class="hint"></div><div class="split">${phases.map((_,i)=>moodBlock(i)).join('')}</div>${field('awareness','When did you first notice a change?','At the start, only afterward, or not sure? What shifted?')}${field('response','R · Thoughts, body sensations, and urges','What did your mind say? What did your body do? What did you want to do?')}`;if(step===2)panel.innerHTML=`${field('pattern','AP · What did you actually do?','Withdraw, scroll, argue, put something off… or a different pattern?')}${field('relief','What did it help with in the short term?','Was there relief or protection?')}${field('cost','What happened later?','What helped, what hurt, and what remained unresolved?')}<div class="notice">A boundary, leaving danger, or taking needed rest can be helpful. Describe the effect rather than judging the action.</div>`;if(step===3)panel.innerHTML=`${field('desired','What outcome would you prefer?','Something within your influence: communicate clearly, protect a boundary…')}${field('cue','What early cue could you recognize next time?','My jaw tightens; I start assuming the worst…')}<label for="skill">A coping option to explore</label><select id="skill"><option value="">Choose or write your own below</option><option>Pause, observe, then choose</option><option>Separate facts from interpretations</option><option>Make one clear request</option><option>Take a planned break and return</option><option>Ask a trusted person for support</option><option>Take one manageable step</option></select>${field('coping','AC · What could you try instead?','Choose a small, safe action that fits your situation.')}${field('plan','My if–then plan','If I notice ___, then I will ___.')}${field('support','What would make this easier?','A reminder, a phrase to rehearse, support, or a smaller first step?')}`;if(step===4)panel.innerHTML=`<div class="notice">You can save an incomplete reflection. Return to it after trying your plan.</div>${recordHTML(draft)}${field('followup','After trying the plan: what happened?','Leave this blank until you have tried it. What would you keep or adjust?')}`;}
function recordHTML(r){return `<h3>${esc(r.title||'Untitled reflection')}</h3><p class="hint">${esc(r.date||'Date not recorded')} · ${esc(r.tags||'No tags')}</p><div class="flow">${[['trigger','Trigger'],['response','Response'],['pattern','Avoidance / behavior pattern'],['relief','Short-term effect'],['cost','Later effect'],['desired','Desired outcome'],['cue','Early cue'],['coping','Alternative coping'],['plan','If–then plan'],['support','Support'],['followup','Follow-up']].map(([k,l])=>r[k]?`<p><b>${l}</b>${esc(r[k]).replace(/\n/g,'<br>')}</p>`:'').join('')}</div><div class="chips">${(r.temps||[]).map((m,i)=>`<span class="pill">${phases[i]}: ${esc([...(m.moods||[]),m.own].filter(Boolean).join(', ')||'not named')} · ${m.intensity??'—'}/10</span>`).join('')}</div>${r.awareness?`<p><b>First noticed:</b> ${esc(r.awareness)}</p>`:''}${r.context?`<p><b>Context:</b> ${esc(r.context)}</p>`:''}`}
function recordPage(){if(!unlocked)return gate();main.innerHTML=`<div class="sectionhead"><div><span class="eyebrow">REFLECTION BECOMES PREPARATION</span><h2>My journal</h2></div><div class="actions"><a class="button primary" href="#journal">New reflection</a>${button('Lock','lock')}</div></div><p>Look for a familiar cue, then rehearse one response you want to try. Entries and intensity ratings describe your experience; they are not a clinical score.</p><label for="search">Find a moment or pattern</label><input id="search" type="search" placeholder="Search titles, tags, feelings, or plans"><div class="actions">${button('Sync with my Sheet','sync')}${button('Encrypted backup','export')}<label class="button" style="margin:0" for="import">Restore backup</label><input id="import" type="file" accept="application/json" hidden></div><p class="hint">${cloudReady?'Sheet connected for this session.':'Google Sheets is not connected. Entries are saved encrypted on this device.'} Back up before clearing browser data.</p><div id="entries"></div>`;entries('')}
function entries(q){const shown=records.filter(r=>!r.deleted).filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase()));$('#entries').innerHTML=shown.length?shown.map(r=>`<article class="card entry"><h3>${esc(r.title||'Untitled reflection')}</h3><p class="hint">${esc(r.date||'No event date')} · ${esc(r.tags||'No tags')}</p><p>${esc(r.plan||'No next-time plan yet. Add one when you are ready.')}</p><div class="actions"><button data-edit="${r.id}">Review / follow up</button><button data-rehearse="${r.id}">Rehearse plan</button><button data-delete="${r.id}">Delete</button></div></article>`).join(''):'<div class="notice">No matching reflections yet. Start with a small, everyday moment.</div>'}
function settingsPage(){if(hosted.enabled)return hostedSettings();main.innerHTML=`<div class="narrow"><span class="eyebrow">MAKE THIS SPACE YOURS</span><h2>Your journal, your way.</h2><section class="card"><label for="theme">Color atmosphere</label><select id="theme"><option value="cyan">Cyber cyan</option><option value="purple" ${settings.theme==='purple'?'selected':''}>Neon purple</option></select><label><input type="checkbox" id="compact" ${settings.compact?'checked':''}> Use shorter writing spaces</label>${button('Save appearance','appearance')}<p class="hint">Every emotion check supports multiple feelings, your own vocabulary, and optional answers.</p></section><section class="card"><span class="eyebrow">VERSION ${APP_VERSION}</span><h2>Set up my Google journal</h2><p>Sign in with Google, approve access, and create your own private Sheet. No scripts or connection tokens to copy.</p>${HOSTED_URL?`<a class="button primary" href="${esc(HOSTED_URL)}" target="_blank" rel="noopener">Open Google setup &amp; journal</a>`:`<p class="notice">The hosted service is awaiting its Google deployment. You can use local journaling or the individual connection below.</p>`}<p class="hint">The Google workspace opens separately. Export an encrypted backup here before moving an existing journal; restore it there with the same passphrase, then sync.</p><a href="#setup">Setup guide</a></section><h2>Individual Google Sheet connection</h2><p><a class="button" href="#setup">Step-by-step Google Sheet &amp; Apps Script setup</a></p><p>Each person uses their own Apps Script deployment and private Sheet. Only encrypted journal data is stored there. Your passphrase is never sent to Google.</p><div class="notice">Connection requires the included Apps Script setup. Do not enter a shared public spreadsheet. Keep the access token separate from your journal passphrase.</div><label for="endpoint">Apps Script web app URL</label><input id="endpoint" type="url" value="${esc(settings.endpoint)}" placeholder="https://script.google.com/macros/s/…/exec"><label for="token">Private access token</label><input id="token" type="password" autocomplete="off" value="" placeholder="From your Apps Script setup"><p class="hint">Token is kept in memory for this session. The endpoint URL and appearance preferences stay on this device.</p><div class="actions">${button('Save settings & connect','connect','primary')}${button('Disconnect Sheet','disconnect')}${button('Lock journal','lock')}</div><p class="hint">Source code includes a full setup guide, data format, privacy notes, and deployment instructions. GitHub Pages hosts only the app; it never stores your journal.</p></div>`}
async function persist(){localStorage.setItem(storageKey,JSON.stringify(await seal(records,pass)))}
async function unlock(){const p=$('#pass').value;if(p.length<12)throw Error('Use a passphrase of at least 12 characters.');const saved=localStorage.getItem(storageKey);let loaded=[];try{if(saved)loaded=validateRecords(await open(JSON.parse(saved),p))}catch{throw Error('Could not unlock. Check the passphrase; your saved journal has not changed.')}pass=p;records=loaded;unlocked=true;render()}
function resetDraft(){draft={id:crypto.randomUUID(),date:new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),temps:phases.map(()=>({moods:[],intensity:null,own:''}))};step=0}
function render(){const route=location.hash||'#home';if(route==='#learn')learn();else if(route==='#journal'){if(!draft.id)resetDraft();journal()}else if(route==='#records')recordPage();else if(route==='#settings')settingsPage();else if(route==='#setup')setupPage();else home();window.scrollTo(0,0)}
function lock(){pass='';records=[];draft={};unlocked=false;cloudToken='';cloudReady=false;bridge=null;document.querySelector('#cloudframe')?.remove();notify('Journal locked. Unsaved draft cleared.');render()}
async function connect(){const url=$('#endpoint').value.trim(),token=$('#token').value;settings.theme=$('#theme').value;settings.compact=$('#compact').checked;if(!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(url))throw Error('Use the deployed Apps Script /exec URL.');if(token.length<32)throw Error('Enter the private access token from setup.');settings.endpoint=url;localStorage.setItem('traptrack.settings',JSON.stringify(settings));apply();cloudToken=token;await loadBridge();try{await rpc('read')}catch(error){cloudReady=false;throw error}notify('Connected. Unlock your journal, then sync from My journal.');}
function loadBridge(){cloudReady=false;bridge=null;document.querySelector('#cloudframe')?.remove();nonce=crypto.randomUUID();return new Promise((resolve,reject)=>{const frame=document.createElement('iframe');frame.id='cloudframe';frame.hidden=true;frame.title='Private Google Sheets connection';frame.src=settings.endpoint+'?nonce='+encodeURIComponent(nonce);document.body.append(frame);const timer=setTimeout(()=>{delete window.bridgeResolve;reject(Error('Connection timed out. Check Apps Script deployment and ALLOWED_ORIGIN.'))},25000);window.bridgeResolve=()=>{clearTimeout(timer);delete window.bridgeResolve;cloudReady=true;resolve()}})}
window.addEventListener('message',e=>{if(!/^https:\/\/[a-z0-9-]+-script\.googleusercontent\.com$/.test(e.origin)&&e.origin!=='https://script.googleusercontent.com'&&e.origin!=='https://script.google.com')return;const d=e.data;if(d?.kind==='trap-ready'&&d.nonce===nonce&&window.bridgeResolve){bridge={source:e.source,origin:e.origin};window.bridgeResolve();return}if(!bridge||e.source!==bridge.source||e.origin!==bridge.origin)return;const p=pending.get(d?.id);if(!p)return;pending.delete(d.id);clearTimeout(p.timer);d.error?p.reject(Error(d.error)):p.resolve(d.result)});
function rpc(action,payload){if(hosted.enabled)return hosted.request(action,payload);if(!cloudReady||!bridge||!cloudToken)throw Error('Connect your Sheet from Settings first.');return new Promise((resolve,reject)=>{const id=crypto.randomUUID(),timer=setTimeout(()=>{pending.delete(id);reject(Error('Sync timed out. Your local journal is safe; try again.'))},30000);pending.set(id,{resolve,reject,timer});bridge.source.postMessage({kind:'trap-request',id,token:cloudToken,action,payload},bridge.origin)})}
async function sync(){if(!unlocked)throw Error('Unlock your journal first.');if(hosted.enabled){const account=await hosted.request('status');if(!account.configured)throw Error('Create your private Sheet from Settings first.');if(settings.boundHostedSheet&&settings.boundHostedSheet!==account.sheetUrl)throw Error('This browser journal is linked to another Google Sheet. Use a separate browser profile for this Google account.');if(!settings.boundHostedSheet&&records.length&&!confirm('Sync the reflections in this browser journal to the currently signed-in Google account? Check that these are the records you intend to copy.'))return;hostedInfo=account;}const result=await rpc('read');let remote=[];if(result.envelope){try{remote=validateRecords(await open(result.envelope,pass))}catch{throw Error('Sheet uses a different passphrase or damaged data. Nothing was overwritten.')}}records=mergeRecords(records,remote);await persist();const written=await rpc('write',{envelope:await seal(records,pass),revision:result.revision});if(!written.ok)throw Error('Sheet changed during sync. Sync again to merge the latest records.');if(hosted.enabled){settings.boundHostedSheet=hostedInfo.sheetUrl;localStorage.setItem('traptrack.settings',JSON.stringify(settings));}notify('Encrypted journal synced with your Google Sheet.');recordPage()}
main.addEventListener('input',e=>{const t=e.target;if(t.dataset.field)draft[t.dataset.field]=t.value;if(t.dataset.own!==undefined)draft.temps[+t.dataset.own].own=t.value;if(t.dataset.intensity!==undefined){draft.temps[+t.dataset.intensity].intensity=+t.value;$('#out'+t.dataset.intensity).textContent=t.value}if(t.id==='search')entries(t.value)});
main.addEventListener('change',async e=>{if(e.target.id==='mixed')$('#mixhint').textContent=e.target.value?`For some people, ${e.target.value.toLowerCase()} may include ${mixed[e.target.value].join(', ').toLowerCase()}. Does any of that fit? Choose your own combination below.`:'';if(e.target.id==='skill'&&e.target.value){draft.coping=e.target.value;$('#coping').value=draft.coping}if(e.target.id==='import'){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Backup too large.');const data=await open(JSON.parse(await file.text()),pass);records=mergeRecords(records,validateRecords(data));await persist();notify('Backup merged into this journal.');recordPage()}catch{notify('Could not restore. Check the backup file and passphrase.')}}});
main.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;try{if(t.dataset.zero!==undefined||t.dataset.clearIntensity!==undefined){const i=+(t.dataset.zero??t.dataset.clearIntensity);draft.temps[i].intensity=t.dataset.zero!==undefined?0:null;$('#out'+i).textContent=draft.temps[i].intensity??'not recorded';$('#intensity'+i).value=0;return}if(t.dataset.mood){const m=draft.temps[+t.dataset.phase].moods;const i=m.indexOf(t.dataset.mood);i<0?m.push(t.dataset.mood):m.splice(i,1);t.setAttribute('aria-pressed',i<0?'true':'false');return}if(t.dataset.edit){draft=structuredClone(records.find(r=>r.id===t.dataset.edit));step=0;location.hash='#journal';journal();return}if(t.dataset.rehearse){const r=records.find(r=>r.id===t.dataset.rehearse);main.innerHTML=`<div class="narrow card"><span class="eyebrow">PRACTICE BEFORE THE MOMENT</span><h2>${esc(r.title||'Your next step')}</h2><p><b>When I notice:</b> ${esc(r.cue||'Add an early cue in your reflection.')}</p><h3>${esc(r.plan||'Add an if–then plan in your reflection.')}</h3><p>${esc(r.support||'What support would help?')}</p><p class="notice">Imagine a manageable version of the situation. Say your plan once. What is the smallest first action you could take? You can stop at any point.</p><button data-edit="${r.id}">Adjust this plan</button> ${button('Back to journal','records')}</div>`;return}if(t.dataset.delete){if(!confirm('Delete this reflection? This also removes it from the synced journal on your next sync. Older backups and Google revision history may still contain it.'))return;const id=t.dataset.delete;records=records.filter(r=>r.id!==id);records.push({id,updated:new Date().toISOString(),deleted:true});await persist();recordPage();return}const a=t.dataset.action;if(!a)return;t.disabled=true;if(a==='records')recordPage();if(a==='unlock')await unlock();if(a==='next'){step++;journal()}if(a==='back'){step--;journal()}if(a==='save'){draft.updated=new Date().toISOString();records=records.filter(r=>r.id!==draft.id);records.unshift(structuredClone(draft));await persist();resetDraft();location.hash='#records';notify('Saved encrypted on this device. Sync when you want to update your Sheet.')}if(a==='lock'){if(draft.id&&Object.values(draft).some(v=>typeof v==='string'&&v.length>40)&&!confirm('Lock and clear the unsaved draft?'))return;lock()}if(a==='appearance'){settings.theme=$('#theme').value;settings.compact=$('#compact').checked;localStorage.setItem('traptrack.settings',JSON.stringify(settings));apply();notify('Appearance saved.')}if(a==='individual-guide')individualSetupPage();if(a==='hosted-status'){hostedInfo=await hosted.request('status');cloudReady=true;hostedSettings()}if(a==='hosted-setup'){hostedInfo=await hosted.request('setup');cloudReady=true;hostedSettings();notify('Your private Google Sheet is ready. Unlock your journal, then sync.')}if(a==='connect')await connect();if(a==='disconnect'){cloudToken='';cloudReady=false;bridge=null;document.querySelector('#cloudframe')?.remove();delete settings.endpoint;localStorage.setItem('traptrack.settings',JSON.stringify(settings));notify('Sheet disconnected.');settingsPage()}if(a==='sync')await sync();if(a==='export'){const blob=new Blob([JSON.stringify(await seal(records,pass))],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='trap-track-encrypted-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(err){notify(err.message)}finally{t.disabled=false}});
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',e=>{if(unlocked&&draft.id&&(draft.title||draft.trigger||draft.response)){e.preventDefault();e.returnValue=''}});if(window.parent===window&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('Offline installation is unavailable in this browser.'));render();


function individualSetupPage(){main.innerHTML="<style>.setup-guide pre{white-space:pre;overflow:auto;padding:1rem;background:#020617;border-radius:16px;max-height:32rem}.setup-guide table{width:100%;border-collapse:collapse}.setup-guide td,.setup-guide th{text-align:left;vertical-align:top;padding:.75rem;border-bottom:1px solid #64748b;overflow-wrap:anywhere}.setup-guide li{margin-bottom:.8rem}.setup-guide code{overflow-wrap:anywhere}.setup-guide summary{cursor:pointer}.setup-guide a{overflow-wrap:anywhere}</style><div class=\"narrow setup-guide\"><p class=\"eyebrow\">PNiXStudio · CLIENT SETUP</p><h1>Connect your private journal</h1><p>You can use Trap Track locally without Google. To sync across devices, create your own Google Apps Script (GAS) project and private Sheet. Allow about 20–30 minutes; a desktop browser makes copying files easier.</p><p><a class=\"button\" href=\"#settings\">Back to Settings</a></p>\n<section class=\"card\"><h2>1. Before you begin</h2><p>Sign into the Google account that should own your journal. Each person needs a separate project, Sheet, token, and passphrase. You do not need your own GitHub repository to use the hosted app.</p><p>Keep a password manager ready. Your Google password, the connection access token, and your journal passphrase are three different things. Never send any of them to support.</p></section>\n<section class=\"card\"><h2>2. Create the Apps Script project</h2><ol><li>Open <a href=\"https://script.google.com/home\" target=\"_blank\" rel=\"noopener\">Google Apps Script</a>. Confirm the correct Google account using the profile picture.</li><li>Choose <b>New project</b>. Rename “Untitled project” to <b>Trap Track — My private journal</b>.</li><li>In the Editor, open <b>Code.gs</b>. Select all its default code and replace it with the complete Code.gs contents below. Copy only the code inside the panel.</li><li>Next to Files, click <b>+ → HTML</b>. Enter <b>Bridge</b> as the name (Google adds .html). Replace all its contents with Bridge.html below.</li><li>Open <b>Project Settings</b> (gear). Enable <b>Show “appsscript.json” manifest file in editor</b>. Return to Editor, open appsscript.json, and replace its complete contents with the manifest below.</li><li>Save the project with the save icon or Ctrl+S / Cmd+S. All three files must be present.</li></ol><p>No Sheet needs to be created manually. The setup function creates and formats it in the next step.</p><details><summary>Code.gs — expand and copy all code</summary><pre tabindex=\"0\"><code>/** Trap Track: one deployment and private spreadsheet per individual. */\nfunction setup() {\n  const p = PropertiesService.getScriptProperties();\n  if (!p.getProperty(&#x27;SHEET_ID&#x27;)) {\n    const ss = SpreadsheetApp.create(&#x27;Trap Track · Private encrypted journal&#x27;);\n    const sheet = ss.getSheets()[0]; sheet.setName(&#x27;Vault&#x27;);\n    sheet.getRange(&#x27;A1:D1&#x27;).setValues([[&#x27;Revision&#x27;,&#x27;Updated UTC&#x27;,&#x27;Encrypted chunk&#x27;,&#x27;Format&#x27;]]);\n    sheet.getRange(&#x27;A1:D1&#x27;).setBackground(&#x27;#183439&#x27;).setFontColor(&#x27;#ffffff&#x27;).setFontWeight(&#x27;bold&#x27;);\n    sheet.setFrozenRows(1); sheet.setColumnWidth(1,120);sheet.setColumnWidth(2,210);sheet.setColumnWidth(3,600);\n    p.setProperty(&#x27;SHEET_ID&#x27;, ss.getId());\n  }\n  if (!p.getProperty(&#x27;ACCESS_TOKEN&#x27;)) p.setProperty(&#x27;ACCESS_TOKEN&#x27;, Utilities.getUuid()+Utilities.getUuid());\n  // Set ALLOWED_ORIGIN in Project Settings &gt; Script Properties, for example:\n  // https://jthatcher87.github.io (origin only, no repository path).\n  // Token is visible only in Script Properties; do not put it in code or logs.\n}\nfunction doGet(e) {\n  const p=PropertiesService.getScriptProperties();\n  const origin=p.getProperty(&#x27;ALLOWED_ORIGIN&#x27;)||&#x27;&#x27;;\n  if (!/^https:\\/\\/[a-zA-Z0-9.-]+(?::[0-9]+)?$/.test(origin)) return HtmlService.createHtmlOutput(&#x27;Set a valid HTTPS ALLOWED_ORIGIN in Script Properties.&#x27;);\n  const t=HtmlService.createTemplateFromFile(&#x27;Bridge&#x27;);\n  t.origin=origin;t.nonce=String(e.parameter.nonce||&#x27;&#x27;).replace(/[^a-zA-Z0-9-]/g,&#x27;&#x27;);\n  return t.evaluate().setTitle(&#x27;Trap Track private connection&#x27;).setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);\n}\nfunction journalApi(request) {\n  const p=PropertiesService.getScriptProperties(), expected=p.getProperty(&#x27;ACCESS_TOKEN&#x27;);\n  if (!expected || !request || typeof request.token!==&#x27;string&#x27; || !equal_(expected,request.token)) throw new Error(&#x27;Connection not authorized. Check your private access token.&#x27;);\n  const lock=LockService.getScriptLock();lock.waitLock(10000);\n  try {\n    const ss=SpreadsheetApp.openById(p.getProperty(&#x27;SHEET_ID&#x27;)),sheet=ss.getSheetByName(&#x27;Vault&#x27;);\n    const rows=sheet.getLastRow(), revision=rows&gt;1?String(sheet.getRange(2,1).getValue()):&#x27;0&#x27;;\n    if(request.action===&#x27;read&#x27;) {\n      const text=rows&gt;1?sheet.getRange(2,3,rows-1,1).getValues().map(r=&gt;{if(typeof r[0]!==&#x27;string&#x27;||r[0].slice(0,3)!==&#x27;v1:&#x27;)throw new Error(&#x27;Invalid journal chunk.&#x27;);return r[0].slice(3);}).join(&#x27;&#x27;):&#x27;&#x27;;\n      return {revision:revision,envelope:text?JSON.parse(text):null};\n    }\n    if(request.action!==&#x27;write&#x27;)throw new Error(&#x27;Unknown journal action.&#x27;);\n    const payload=request.payload||{};\n    if(String(payload.revision)!==revision)return {ok:false,conflict:true};\n    const v=payload.envelope;\n    if(!v || v.v!==1 || !/^[A-Za-z0-9+/=]+$/.test(v.data||&#x27;&#x27;) || !/^[A-Za-z0-9+/=]{24}$/.test(v.salt||&#x27;&#x27;) || !/^[A-Za-z0-9+/=]{16}$/.test(v.iv||&#x27;&#x27;))throw new Error(&#x27;Invalid encrypted journal.&#x27;);\n    const text=JSON.stringify(v);if(text.length&gt;1500000)throw new Error(&#x27;Journal exceeds 1.5 MB. Export a backup and archive older entries.&#x27;);\n    const next=Utilities.getUuid(),now=new Date().toISOString(),out=[];\n    for(let i=0;i&lt;text.length;i+=40000)out.push([next,now,&#x27;v1:&#x27;+text.slice(i,i+40000),&#x27;AES-GCM / PBKDF2-SHA256 v1&#x27;]);\n    // Prefix every chunk so no chunk can be interpreted as a spreadsheet formula.\n    if(sheet.getMaxRows()&lt;out.length+1)sheet.insertRowsAfter(sheet.getMaxRows(),out.length+1-sheet.getMaxRows());\n    sheet.getRange(2,1,out.length,4).setNumberFormat(&#x27;@&#x27;).setValues(out);\n    if(rows&gt;out.length+1)sheet.getRange(out.length+2,1,rows-out.length-1,4).clearContent();\n    SpreadsheetApp.flush();return {ok:true,revision:next};\n  } finally {lock.releaseLock();}\n}\nfunction equal_(a,b) {\n const x=Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,a),y=Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,b);\n let diff=0;for(let i=0;i&lt;x.length;i++)diff|=x[i]^y[i];return diff===0;\n}\n\n</code></pre></details><details><summary>Bridge.html — expand and copy all code</summary><pre tabindex=\"0\"><code>&lt;!doctype html&gt;&lt;html&gt;&lt;head&gt;&lt;base target=&quot;_top&quot;&gt;&lt;/head&gt;&lt;body&gt;&lt;script&gt;\nconst allowedOrigin=&lt;?!= JSON.stringify(origin) ?&gt;;\nconst nonce=&lt;?!= JSON.stringify(nonce) ?&gt;;\nwindow.addEventListener(&#x27;message&#x27;,function(e){\n if(e.origin!==allowedOrigin || e.source!==window.top || e.data?.kind!==&#x27;trap-request&#x27;)return;\n const request=e.data;\n google.script.run.withSuccessHandler(function(result){window.top.postMessage({id:request.id,result:result},allowedOrigin);})\n .withFailureHandler(function(error){window.top.postMessage({id:request.id,error:error.message||&#x27;Google Sheets request failed.&#x27;},allowedOrigin);})\n .journalApi({token:request.token,action:request.action,payload:request.payload});\n});\nwindow.top.postMessage({kind:&#x27;trap-ready&#x27;,nonce:nonce},allowedOrigin);\n&lt;/script&gt;&lt;/body&gt;&lt;/html&gt;\n\n</code></pre></details><details><summary>appsscript.json — expand and copy all code</summary><pre tabindex=\"0\"><code>{&quot;timeZone&quot;:&quot;Etc/UTC&quot;,&quot;dependencies&quot;:{},&quot;exceptionLogging&quot;:&quot;STACKDRIVER&quot;,&quot;runtimeVersion&quot;:&quot;V8&quot;,&quot;oauthScopes&quot;:[&quot;https://www.googleapis.com/auth/spreadsheets&quot;]}\n\n</code></pre></details></section>\n<section class=\"card\"><h2>3. Run setup and authorize Google</h2><ol><li>In Editor, select <b>setup</b> in the function dropdown next to Run. Click <b>Run</b>. Do not run doGet or journalApi directly.</li><li>When asked, click <b>Review permissions</b>, then choose the same Google account.</li><li>Read the permission request. The script requests access to your spreadsheets; this is broader than a single Sheet. The supplied code uses the journal Sheet ID it creates.</li><li>A personal script may show “Google hasn’t verified this app.” Continue only for the project you just created with the supplied code, after reviewing it and the requested access. If offered, use <b>Advanced → Go to [your project name] (unsafe)</b>, then grant the requested spreadsheet access. If Google or your organization blocks it, do not bypass the policy; use local journaling and ask your administrator.</li><li>Complete any Google phone/security checks directly with Google. Wait for <b>Execution completed</b> in the execution log. If authorization interrupts the run, select setup and Run again.</li></ol><p>Successful setup creates <b>Trap Track · Private encrypted journal</b> with a <b>Vault</b> tab, plus SHEET_ID and ACCESS_TOKEN in Script Properties. Running the supplied setup again reuses the existing Sheet and token.</p></section>\n<section class=\"card\"><h2>4. Check the Sheet and connection properties</h2><ol><li>Open <b>Project Settings → Script Properties</b>. Refresh if necessary. Copy ACCESS_TOKEN into your password manager; keep its entire value.</li><li>Add a property named <b>ALLOWED_ORIGIN</b>. For the hosted Trap Track app, enter exactly <code>https://jthatcher87.github.io</code>. Save properties. Do not include /trap-track/, a trailing slash, spaces, or quotes.</li><li>Find the new Sheet in <a href=\"https://drive.google.com/\" target=\"_blank\" rel=\"noopener\">Google Drive</a>, or open <code>https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit</code> using your own SHEET_ID value.</li><li>Check Share → General access is <b>Restricted</b>. Do not publish the Sheet to the web or share it with other clients.</li></ol><table><thead><tr><th>Property</th><th>What to use</th></tr></thead><tbody><tr><td>SHEET_ID</td><td>Generated by setup; leave unchanged.</td></tr><tr><td>ACCESS_TOKEN</td><td>Generated by setup; private connection credential.</td></tr><tr><td>ALLOWED_ORIGIN</td><td>HTTPS app origin only. For your own hosting, use its actual origin.</td></tr></tbody></table><p>The Vault header row should read Revision, Updated UTC, Encrypted chunk, Format. Before the first sync there are no journal rows. Do not rename Vault, edit its cells, sort its rows, or insert formulas. It stores an encrypted snapshot, not one readable row per reflection.</p><p>GitHub Pages repository paths share an origin. For a separately hosted app, use that hosting origin; a dedicated custom domain gives a tighter origin boundary.</p></section>\n<section class=\"card\"><h2>5. Deploy your web app</h2><ol><li>In Apps Script, choose <b>Deploy → New deployment</b>.</li><li>Next to Select type, open the gear menu and choose <b>Web app</b>.</li><li>Enter a description such as “Trap Track journal connection v1”. Set <b>Execute as: Me</b> (the journal owner).</li><li>Set <b>Who has access: Anyone</b>. “Anyone with Google account” is not equivalent: the app’s background connection needs access without an interactive Google sign-in.</li><li>Choose <b>Deploy</b> and complete any authorization Google requests.</li><li>Copy the <b>Web app URL</b> ending in <b>/exec</b> into your password manager. Do not use the deployment ID, editor URL, Sheet URL, or a /dev test URL.</li></ol><p>“Anyone” makes the connection bridge reachable; it does not make the Sheet public. Journal reads and writes still require your access token, and journal content is encrypted in the app. Anyone who obtains the token can download or replace encrypted data, even without its passphrase. If Anyone is unavailable under your account policy, this connection cannot be used as configured; continue locally.</p></section>\n<section class=\"card\"><h2>6. Connect Trap Track</h2><ol><li>Open <a href=\"#settings\">Trap Track → Settings</a>.</li><li>Paste your /exec Web app URL into <b>Apps Script web app URL</b>.</li><li>Paste your ACCESS_TOKEN into <b>Private access token</b>, then choose <b>Save settings &amp; connect</b>.</li><li>Wait for “Connected. Unlock your journal, then sync from My journal.” Connection checks access; it does not upload your reflections by itself.</li><li>Open <b>My journal</b> and enter a unique passphrase of at least 12 characters. On an existing journal, use its existing passphrase. Store a recovery copy yourself: the app cannot reset it or recover encrypted content.</li></ol><p>Your token and passphrase stay in memory for the session. Reconnect after locking or closing the app. The endpoint and appearance preferences remain on this device.</p></section>\n<section class=\"card\"><h2>7. Verify with a harmless test</h2><ol><li>Create a reflection titled “Connection test” with no personal information. Continue through the steps and choose <b>Save reflection</b>.</li><li>In <b>My journal</b>, choose <b>Sync with my Sheet</b>. Wait for “Encrypted journal synced with your Google Sheet.” A local-save message alone does not confirm cloud sync.</li><li>Open your Sheet. Vault should now show a revision, UTC timestamp, encrypted chunk(s) beginning with <code>v1:</code>, and format. Unreadable content is expected.</li><li>For a full read-back check, open the app in a second browser profile or device with no existing local journal. Connect using the same endpoint and token, unlock using the same passphrase, and sync. Confirm “Connection test” appears. Never clear your only local copy to run this check.</li><li>Delete “Connection test” inside the app, sync, then sync any second device. The test should disappear. Do not clear Vault cells manually; Google history and backups may retain older snapshots.</li></ol><p>Setup is complete when connection succeeds, a sync is acknowledged, and a clean second device can read the test. Until then, keep an encrypted backup of any real entries.</p></section>\n<section class=\"card\"><h2>8. Everyday use and another device</h2><p>Save reflections to this device, then sync whenever you want the Sheet updated. Sync needs Internet and is manual. On another device, open the same app, connect with the same endpoint/token, use the same passphrase, then sync. Sync before and after editing when moving between devices; keep device clocks accurate.</p><p>Use <b>My journal → Encrypted backup</b> regularly. Restore backup requires its passphrase. Lock the journal on shared devices. Clearing browser data can remove local records; unsaved drafts are lost when closing or locking. The Sheet is storage, not a readable clinician dashboard or emergency monitoring service.</p></section>\n<section class=\"card\"><h2>Troubleshooting</h2><table><thead><tr><th>What you see</th><th>What to check</th></tr></thead><tbody><tr><td>setup is missing / syntax error</td><td>Save Code.gs, copy the entire file without Markdown fences, and check that Bridge is an HTML file.</td></tr><tr><td>No Sheet or properties</td><td>Run setup under the correct account, complete authorization, and check the execution log. Refresh Script Properties.</td></tr><tr><td>Connection timed out</td><td>Check Internet, exact ALLOWED_ORIGIN, /exec URL, Anyone access, and that the deployed version includes all three files. Browser privacy extensions may block the embedded bridge; try a supported browser/profile without changing account security settings.</td></tr><tr><td>Connection not authorized</td><td>Copy the full ACCESS_TOKEN from the matching project. Remove accidental spaces. Reconnect after a token change.</td></tr><tr><td>No HTML file named Bridge</td><td>Create an HTML file named Bridge, paste Bridge.html, save, and deploy a new version.</td></tr><tr><td>Different passphrase or damaged data</td><td>Use the original journal passphrase. Do not delete data, replace SHEET_ID, or create a new passphrase over the existing journal. Preserve backups.</td></tr><tr><td>Sheet changed during sync</td><td>Finish syncing on other devices, then sync again to merge. Concurrent edits to one reflection use the latest device timestamp.</td></tr><tr><td>Permission denied / Sheet missing</td><td>Confirm Execute as Me, the owner account, SHEET_ID, the Sheet is not trashed, and Vault exists. Reauthorize if you revoked access.</td></tr><tr><td>Quota or size limit</td><td>Keep an encrypted backup. Retry quota failures later. The backend accepts snapshots up to 1.5 MB; do not edit encrypted chunks to shrink them.</td></tr></tbody></table></section>\n<section class=\"card\"><h2>Updates, token changes, and stopping sync</h2><p><b>Update code:</b> export an encrypted backup first. Replace the relevant project files without deleting Script Properties. Choose Deploy → Manage deployments → select the existing web app → Edit (pencil) → Version: New version → Deploy. Keeping the deployment preserves its URL. Merely saving code does not update a versioned deployment.</p><p><b>Exposed token:</b> replace ACCESS_TOKEN in Script Properties with a new long, randomly generated secret (at least 32 characters; use a password manager generator). Save and reconnect each device with the new token. Do not change the passphrase or SHEET_ID. Property changes apply without a new code deployment.</p><p><b>Stop cloud access:</b> Disconnect Sheet in app Settings clears the local connection; it does not revoke the remote endpoint. To disable that endpoint, archive the deployment through Deploy → Manage deployments. Export a backup before removing the Sheet or script. Deleting a reflection and syncing is a logical deletion; history and backups can retain older copies.</p><p><b>Getting help:</b> share the exact error text and which numbered step failed. Redact tokens, passphrases, Sheet IDs, deployment URLs, account information, and journal text from screenshots.</p></section>\n<section class=\"card\"><h2>Google reference documentation</h2><p><a href=\"https://developers.google.com/apps-script/guides/web\">Deploying Apps Script web apps</a> · <a href=\"https://developers.google.com/apps-script/concepts/manifests\">Showing and editing the manifest</a></p><p class=\"hint\">Google labels can vary by account and policy. These instructions match the supplied backend files.</p></section></div>";}

function hostedSettings(){
 main.innerHTML=`<div class="narrow"><span class="eyebrow">TRAP TRACK ${APP_VERSION} · GOOGLE WORKSPACE</span><h1>Your private Google journal</h1><p>This workspace runs as the Google account you signed in with. It keeps a separate private Sheet for each person. Your journal passphrase stays inside this app; Google receives encrypted journal content.</p><p><a href="#setup">Setup guide</a></p><section class="card"><h2>1. Create or find your Sheet</h2><p>Choose “Check my connection” to find a Sheet you created here before. Choose “Create my private Sheet” to create it if this is your first visit. Repeating setup reuses the same Sheet.</p>${hosted.ready?`${button('Check my connection','hosted-status')}${button('Create my private Sheet','hosted-setup','primary')}`:'<p class="notice">Waiting for the Google connection. If this persists, reopen the hosted setup link.</p>'}${hostedInfo?.configured?`<p class="notice">Your Sheet is ready.</p><a href="${esc(hostedInfo.sheetUrl)}" target="_blank" rel="noopener">Open my private Sheet</a>`:''}</section><section class="card"><h2>2. Unlock, reflect, and sync</h2><p>Use a unique passphrase of at least 12 characters. For an existing journal or backup, use its original passphrase.</p><a class="button" href="#records">Open my journal</a><p>Save a reflection, then choose “Sync with my Sheet” in My journal. Sync is manual. Check the confirmation before switching devices.</p><p class="hint">Google sign-in does not unlock encrypted entries. On another device, use this same hosted service, the same Google account, and the same journal passphrase.</p></section><details><summary>Moving from an individual connection or standalone app</summary><p>In your old journal, sync first and export an encrypted backup. Here, unlock with that same passphrase, restore the backup in My journal, then sync. Check your entries before removing anything from the old journal. Existing private deployments remain supported. The new service creates its own Sheet; it does not modify your old Sheet.</p></details><p><a href="#learn">Learn</a> · <a href="#records">My journal</a> · ${button('Lock journal','lock')}</p><p class="hint">Local storage in an embedded Google workspace may be separate from the standalone PWA and can be restricted by browser privacy settings. Keep encrypted backups. The Google workspace requires Internet; the standalone PWA remains the offline option.</p></div>`;
}
function setupPage(){
 main.innerHTML=`<div class="narrow"><span class="eyebrow">TRAP TRACK ${APP_VERSION} · SETUP GUIDE</span><h1>Set up your Google journal</h1><ol><li>From Settings, open “Google setup &amp; journal”. Sign into the Google account that should own the Sheet.</li><li>Review Google's requested spreadsheet and account identity permissions. Complete any account verification directly with Google. Google may show an unverified-app warning until the owner completes verification; organization restrictions may prevent access.</li><li>In the Google workspace, choose “Create my private Sheet”. The service creates the formatted Vault and remembers it for your Google account. Repeating setup reuses it.</li><li>Open My journal and unlock with a unique passphrase of at least 12 characters. Keep a recovery copy yourself.</li><li>Save a harmless “Connection test” reflection, then “Sync with my Sheet”. Wait for the sync confirmation. Open your Sheet to check its revision and encrypted chunks.</li><li>On another device, open the same Google workspace with the same Google account and passphrase, then sync to verify the test appears. Delete the test inside the app and sync again.</li></ol><section class="card"><h2>Already using Trap Track?</h2><p>Sync and export an encrypted backup from your current journal. In the Google workspace, use the same passphrase, restore that backup, then sync. Verify your entries before removing the old copy. Do not paste your old access token into the new service.</p></section><h2>Privacy and recovery</h2><p>Your Sheet remains private to your account unless you share it. The hosted app handles encrypted content and account-specific storage; its operator controls the service code. Your passphrase is never sent to the service. Anyone using your unlocked journal can read it. There is no passphrase reset that recovers old content.</p><h2>If setup fails</h2><p>Confirm the correct Google account, approved permissions, and Internet connection. If Google blocks access or the service says it must run as the signed-in user, contact the app owner; use local journaling in the meantime. Embedded storage restrictions may require a different browser. Do not clear your only local journal. No automatic migration, background sync, or secure erasure from Google history is implied.</p><h2>Disconnecting</h2><p>Lock the journal before leaving a shared device. Closing the workspace ends its in-page connection. To revoke service access, use your Google Account's third-party connections controls. Your Sheet and backups remain until you remove them yourself.</p><p><a class="button" href="#settings">Back to Settings</a> ${button('Individual deployment instructions','individual-guide')}</p></div>`;
}
